// Initialize streaming response object
const response = {
  message: '',
  processUpdates: [],
  components: [],
  conversationSummary: null
};

// Add process update
function addProcessUpdate(status, message) {
  response.processUpdates.push({
    type: 'process_update',
    status,
    message
  });
}

// Add component
function addComponent(type, data) {
  response.components.push({
    type,
    data
  });
}

// Process the message with streaming
async function processMessageWithStreaming(message, context) {
  // Add initial process update
  addProcessUpdate('started', 'Processing your request...');

  // Get conversation history
  const history = context.conversationHistory || [];

  // Add RAG processing update
  addProcessUpdate('in_progress', 'Retrieving relevant information...');

  // Process through RAG system
  const ragResponse = await $node['OpenAI Chat Model'].execute({
    message,
    history,
    stream: true
  });

  // Stream the response
  for await (const chunk of ragResponse) {
    response.message += chunk.text;

    // Add progress update for each significant chunk
    if (chunk.text.length > 50) {
      addProcessUpdate('in_progress', 'Generating response...');
    }

    // Check for structured data in the response
    if (chunk.metadata?.components) {
      addComponent(chunk.metadata.componentType, chunk.metadata.data);
    }
  }

  // Generate conversation summary
  if (history.length > 0) {
    addProcessUpdate('in_progress', 'Updating conversation summary...');
    const summaryResponse = await $node['OpenAI Chat Model'].execute({
      message: 'Summarize this conversation:\n' + history.map(h => `${h.role}: ${h.content}`).join('\n'),
      stream: false
    });
    response.conversationSummary = summaryResponse.text;
  }

  // Add completion update
  addProcessUpdate('completed', 'Response complete');

  return response;
}

// Process the incoming message
const result = await processMessageWithStreaming($input.item.json.message, $input.item.json.context);

return result;
